const fs = require('fs');
const path = require('path');

function parseConfig(text) {
  // Null-prototype: config text is untrusted input, and a key named
  // `__proto__` or `constructor` must not be able to reach Object.prototype.
  // Callers get a bare object, so it has no inherited `hasOwnProperty`.
  const config = Object.create(null);
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    // A line with no '=' is a bare flag, the form `app.conf` uses for DEBUG.
    if (eq === -1) {
      config[trimmed] = true;
      continue;
    }
    const key = trimmed.slice(0, eq).trim();
    // Fail loudly rather than storing a value under an empty key: a malformed
    // line is a deploy-time mistake worth surfacing at startup.
    if (key === '') {
      throw new Error(`Malformed config line (empty key): ${line}`);
    }
    config[key] = trimmed.slice(eq + 1).trim();
  }
  return config;
}

function loadConfig(filePath) {
  // Read once at startup, before anything is serving: the synchronous call
  // costs nothing that matters here and keeps every caller free of a promise.
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Config file not found: ${path.resolve(filePath)}`);
    }
    throw err;
  }
  return parseConfig(text);
}

module.exports = { parseConfig, loadConfig };

