// Resolve against the module, not the cwd, so the app runs from any directory.
const CONFIG_PATH = path.join(__dirname, '..', 'app.conf');

function main() {
  const config = loadConfig(CONFIG_PATH);
  if (typeof config.name !== 'string') {
    throw new Error(`Config ${CONFIG_PATH} is missing required key: name`);
  }
  console.log(greet(config.name));
}

try {
