}

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');

const { parseConfig, loadConfig } = require('../src/config');

test('parses key=value pairs', () => {
  assert.strictEqual(parseConfig('name=world').name, 'world');
});

test('skips comments and blank lines', () => {
  const config = parseConfig('# a comment\n\n   \nname=world\n');
  assert.deepStrictEqual({ ...config }, { name: 'world' });
});

test('treats a line without = as a bare flag', () => {
  assert.strictEqual(parseConfig('DEBUG').DEBUG, true);
});

test('keeps = characters inside values', () => {
  assert.strictEqual(parseConfig('url=http://x?a=b').url, 'http://x?a=b');
});

test('trims surrounding whitespace from keys and values', () => {
  assert.strictEqual(parseConfig('  name  =  world  ').name, 'world');
});

test('handles CRLF line endings', () => {
  const config = parseConfig('a=1\r\nb=2\r\n');
  assert.deepStrictEqual({ ...config }, { a: '1', b: '2' });
});

test('last duplicate key wins', () => {
  assert.strictEqual(parseConfig('a=1\na=2').a, '2');
});

test('rejects a line with an empty key', () => {
  assert.throws(() => parseConfig('=value'), /empty key/);
});

test('does not pollute Object.prototype', () => {
  parseConfig('__proto__=polluted');
  assert.strictEqual({}.polluted, undefined);
});

test('parses the shipped app.conf', () => {
  const config = loadConfig(path.join(__dirname, '..', 'app.conf'));
  assert.strictEqual(config.name, 'world');
  assert.strictEqual(config.DEBUG, true);
});

test('reports a missing config file by resolved path', () => {
  const missing = path.join(os.tmpdir(), 'definitely-absent.conf');
  fs.rmSync(missing, { force: true });
  assert.throws(() => loadConfig(missing), /Config file not found/);
});

